function boundaryInspection(): SchemaInspection {
  const column = (name: string, dataType: string, tenant = false) => ({
    name,
    data_type: dataType,
    nullable: false,
    generated: false,
    ordinal_position: 1,
    suggestions: {
      tenant,
      conflict: false,
      sensitive: false,
      immutable: name === "id" || tenant,
      large_or_binary: false,
    },
  });
  return {
    engine: "postgres",
    server_version: "PostgreSQL 16",
    current_user: "app_reader",
    inspected_at: "2026-07-25T12:00:00.000Z",
    schemas: ["public"],
    warnings: [],
    role_posture: {
      verified: true,
      superuser: false,
      bypass_rls: false,
      read_only: true,
      writable_relations: [],
      owned_relations: [],
      reasons: [],
    },
    tables: [{
      schema: "public",
      name: "service_visits",
      type: "table",
      writable: true,
      columns: [
        column("id", "uuid"),
        column("tenant_id", "uuid", true),
        { ...column("status", "text"), enum_values: ["scheduled", "completed"] },
        column("scheduled_at", "timestamp"),
      ],
      primary_key: ["id"],
      unique_constraints: [{ name: "service_visits_pkey", columns: ["id"] }],
      foreign_keys: [],
      indexes: [{ name: "service_visits_pkey", columns: ["id"], unique: true }],
      row_level_security: true,
      row_level_security_policies: [{
        name: "tenant_read",
        command: "SELECT",
        permissive: true,
        roles: ["app_reader"],
        using_expression: "(tenant_id = current_setting('app.tenant_id')::uuid)",
      }],
      role_posture: {
        owner: "app_owner",
        current_role_is_owner: false,
        current_role_can_assume_owner: false,
        privileges: {
          select: true,
          insert: false,
          update: false,
          delete: false,
          truncate: false,
          references: false,
          trigger: false,
        },
        row_security_forced: false,
        row_security_effective_for_current_role: true,
      },
      suggestions: {
        tenant_columns: ["tenant_id"],
        conflict_columns: [],
        sensitive_columns: [],
        default_visible_columns: ["id", "tenant_id", "status", "scheduled_at"],
      },
    }],
  };
}

function actionTargetInspection(): SchemaInspection {
  const inspection = boundaryInspection();
  const maintenance = structuredClone(inspection.tables[0]!);
  maintenance.name = "maintenance_requests";
  maintenance.columns = [
    {
      name: "id",
      data_type: "text",
      nullable: false,
      generated: false,
      ordinal_position: 1,
      suggestions: {
        tenant: false,
        conflict: false,
        sensitive: false,
        immutable: true,
        large_or_binary: false,
      },
    },
    {
      name: "tenant_id",
      data_type: "uuid",
      nullable: false,
      generated: false,
      ordinal_position: 2,
      suggestions: {
        tenant: true,
        conflict: false,
        sensitive: false,
        immutable: true,
        large_or_binary: false,
      },
    },
    {
      name: "request_kind",
      data_type: "text",
      nullable: false,
      generated: false,
      ordinal_position: 3,
      enum_values: ["inspection_followup", "repair"],
      suggestions: {
        tenant: false,
        conflict: false,
        sensitive: false,
        immutable: false,
        large_or_binary: false,
      },
    },
    {
      name: "estimated_hours",
      data_type: "integer",
      nullable: false,
      generated: false,
      ordinal_position: 4,
      suggestions: {
        tenant: false,
        conflict: false,
        sensitive: false,
        immutable: false,
        large_or_binary: false,
      },
    },
  ];
  maintenance.primary_key = ["id"];
  maintenance.unique_constraints = [{ name: "maintenance_requests_pkey", columns: ["id"] }];
  maintenance.indexes = [{ name: "maintenance_requests_pkey", columns: ["id"], unique: true }];
  maintenance.suggestions = {
    tenant_columns: ["tenant_id"],
    conflict_columns: [],
    sensitive_columns: [],
    default_visible_columns: ["id", "tenant_id", "request_kind", "estimated_hours"],
  };
  inspection.tables.push(maintenance);
  return inspection;
}

async function staleSemanticRevalidationFixture(options: { readerRls?: boolean; writeback?: "proposal_only" | "supervised"; outcomes?: string[]; unusedVerificationField?: boolean; privateVerificationResource?: boolean; atomicUpdates?: boolean; currentStateRead?: boolean } = {}) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), "synapsor-revalidate-semantic-actions-"));
  const inspection = options.currentStateRead || options.readerRls ? principalScopeInspection() : actionTargetInspection();
  if (options.readerRls) for (const table of inspection.tables) {
    table.row_level_security_policies = [{ name: "review_reader_scope", command: "SELECT", permissive: true, roles: [inspection.current_user],
      using_expression: "tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid AND principal_id = NULLIF(current_setting('app.principal_id', true), '')::uuid" }];
    table.role_posture!.row_security_applicable_policies = ["review_reader_scope"];
  }
  if (options.currentStateRead) {
    const parent = inspection.tables[0]!;
    parent.unique_constraints.push({ name: "current_organization_person", columns: ["tenant_id", "principal_id"] });
    const table = structuredClone(parent);
    table.name = "current_access";
    table.foreign_keys = [{ name: "current_access_subject_fk", columns: ["tenant_id", "principal_id"], referenced_schema: "public",
      referenced_table: parent.name, referenced_columns: ["tenant_id", "principal_id"], delete_rule: "RESTRICT" }];
    for (const name of ["effective_from", "effective_until"]) table.columns.push({ name, data_type: "timestamptz", nullable: false, generated: false,
      ordinal_position: table.columns.length + 1, suggestions: { tenant: false, conflict: false, sensitive: false, immutable: false, large_or_binary: false } });
    inspection.tables.push(table);
  }
  if (options.atomicUpdates) for (const table of inspection.tables) {
    table.columns.push({ name: "c09", data_type: "integer", nullable: false, generated: false,
      ordinal_position: table.columns.length + 1,
      suggestions: { tenant: false, conflict: true, sensitive: false, immutable: false, large_or_binary: false } });
    table.suggestions.conflict_columns = ["c09"];
  }
  if (options.privateVerificationResource) {
    const facts = structuredClone(inspection.tables[0]!);
    facts.name = "visit_facts";
    facts.foreign_keys = [{ name: "visit_facts_visit_fk", columns: ["id"], referenced_schema: "public",
      referenced_table: "service_visits", referenced_columns: ["id"], delete_rule: "RESTRICT" }];
    inspection.tables.push(facts);
  }
  const build = buildAutoBoundary({ inspection, project: { root, package_manager: "npm", frameworks: ["node"],
    schema_inputs: [], database_env_names: ["DATABASE_URL"] }, sourceEnv: "DATABASE_URL", inspectedSchema: "public" });
  const planner = vi.fn(async () => { throw new Error("Stale completed Actions must not be replanned."); });
  const written = await writeAutoBoundaryArtifacts({ projectRoot: root, build });
  if (options.currentStateRead) for (const table of inspection.tables) {
    const preview = await prepareBoundaryResourceReviewMutation(root, { resource_id: `public.${table.name}`, principal_key: "principal_id",
      withhold_from_model_fields: ["principal_id"], actor: "test-reviewer", reason: "Review the fixture's exact existing organization/person scope." }, async () => inspection);
    await commitBoundaryResourceReviewMutation(root, preview);
  }
  if (options.atomicUpdates) for (const table of inspection.tables) {
    const preview = await prepareBoundaryResourceReviewMutation(root, { resource_id: `public.${table.name}`,
      withhold_from_model_fields: ["c09"], private_model_fields: ["c09"], actor: "test-reviewer",
      field_metadata: [{ field: "c09", label: "Source change counter" }],
      reason: "Keep the fixture conflict counter private, including model analysis." }, async () => inspection);
    await commitBoundaryResourceReviewMutation(root, preview);
  }
  const context = await loadBoundaryReviewContext(root);
  const built = buildActionRuleAuthoringCatalog({ boundary: context.candidate, inspection });
  const resource = built.catalog.resources.find((candidate) => candidate.name === "public.service_visits")!;
  const status = structuredClone(resource.fields.find((field) => field.name === "status")!.type);
  const maintenance = built.catalog.resources.find((candidate) => candidate.name === "public.maintenance_requests")!;
  const requestKind = structuredClone(maintenance.fields.find((field) => field.name === "request_kind")!.type);
  const estimatedHours = structuredClone(maintenance.fields.find((field) => field.name === "estimated_hours")!.type);
  const compile = (outcome: string, approvalClass: string) => compileActionRuleModelDraft({
    draft: {
      schema_version: "synapsor.action-rule-model-draft.v1",
      name: outcome,
      outcome,
      verification: { name: `${outcome}.verification`, resources: [{ binding: "visit", resource: "public.service_visits",
        source: { kind: "subject_ref" }, fields: ["status", ...(options.unusedVerificationField ? ["scheduled_at"] : [])] },
        ...(options.atomicUpdates ? [{ binding: "request", resource: "public.maintenance_requests",
          source: { kind: "subject_ref" as const }, fields: ["estimated_hours"] }] : []),
        ...(options.privateVerificationResource ? [{ binding: "facts", resource: "public.visit_facts",
          source: { kind: "relationship" as const, from_binding: "visit", relationship: "visit_facts_visit_fk", direction: "inverse" as const }, fields: ["status"], max_rows: 1 }] : [])] },
      effect: options.atomicUpdates ? { name: `${outcome}.effect`, operation: "update", target_resource: "public.service_visits", target_binding: "visit",
        allowed_fields: [{ name: "status", values: ["completed"] }],
        set: { status: { kind: "literal", value: "completed", value_type: status } }, writeback: options.writeback ?? "proposal_only",
        atomic_updates: [{ operation: "update", target_resource: "public.maintenance_requests", target_binding: "request",
          allowed_fields: [{ name: "estimated_hours", minimum: 1, maximum: 8 }],
          set: { estimated_hours: { kind: "literal", value: 2, value_type: estimatedHours } } }] }
        : { name: `${outcome}.effect`, operation: "insert", target_resource: "public.maintenance_requests",
        allowed_fields: [{ name: "request_kind", values: ["inspection_followup"] },
          { name: "estimated_hours", minimum: 1, maximum: 8 }],
        set: { request_kind: { kind: "literal", value: "inspection_followup", value_type: requestKind },
          estimated_hours: { kind: "literal", value: 2, value_type: estimatedHours } }, writeback: options.writeback ?? "proposal_only" },
      require: { kind: "compare", operator: "eq", left: { kind: "field", binding: "visit", field: "status" },
        right: { kind: "literal", value: "scheduled", value_type: status } },
      derive: {}, approval: { class_name: approvalClass, mode: "human", required_role: "maintenance_reviewer",
        required_approvals: 1, shared_limits: [] }, ttl_seconds: 300,
      review: { when: "The selected visit is scheduled.",
        then: "Propose one inspection follow-up maintenance request for the selected visit.",
        refused: ["The selected visit is not scheduled."], human_review: "One maintenance reviewer approves the proposal.",
        examples: [{ kind: "eligible", scenario: "Scheduled visit", result: "Create a proposal" },
          { kind: "ineligible", scenario: "Completed visit", result: "Refuse" }] },
    }, builtCatalog: built, readBoundary: context.candidate,
    readBoundaryDigest: explorationBoundaryCandidateDigest(context.candidate), activatedAt: "2026-09-08T12:00:00.000Z",
  });
  const compiled = (options.outcomes ?? ["maintenance.complete_visit", "maintenance.close_visit"])
    .map((outcome) => compile(outcome, `${outcome}_approval`));
  const stored = buildActionRuleAuthorityDraft({ name: "reviewed_staging_rules", action_boundary_name: "reviewed_staging_actions",
    catalog: compiled[0]!.loaded.authority.catalog,
    rules: compiled.flatMap((entry) => entry.loaded.authority.rules.map(({ activated_at: _activatedAt, ...rule }) => rule)),
    approval_classes: compiled.flatMap((entry) => entry.loaded.authority.approval_classes),
    reviews: compiled.map((entry) => ({ outcome: entry.rule.outcome, ...entry.review })), now: "2026-09-08T12:00:00.000Z" });
  await writeActionRuleAuthorityDraft(root, stored);
  if (options.privateVerificationResource || options.currentStateRead) {
    const candidate = structuredClone(context.candidate);
    candidate.pack.resources = candidate.pack.resources.filter(resource => resource.id !== "public.visit_facts" && resource.id !== "public.current_access");
    await saveBoundaryReviewProgress(root, createBoundaryReviewProgress({ draft: context.draft, candidate,
      confirmedDecisions: candidate.unresolved_decisions, actor: "test-reviewer", reason: "Keep verification facts private.",
      revision: (context.progress?.revision ?? 0) + 1 }));
  }
  const session: BoundaryReviewInteractiveSession = {
    chooseResource: async () => undefined, editFieldTiers: async () => undefined,
    promptText: async (prompt) => { throw new Error(`Business job must be retained: ${prompt}`); },
    chooseOption: async (title, _options, config) => {
      if (title === "CLIENT INTEGRATION RESPONSIBILITIES") return "assign";

      if (title === "START BOUNDARY DRAFTING") return "resume";
      if (title === "ACTIVATE READ BOUNDARY") return "finish";
      if (title === "FINISH BOUNDARY REVIEW") return "finish";
      if (title === "REPLACE ACTIVE READ BOUNDARY") return "finish";
      throw new Error(`Unexpected completed-Action revalidation menu: ${title}. Context: ${JSON.stringify(config?.context)}. Details: ${JSON.stringify(chats.flatMap(chat => vi.mocked(chat.rememberDetails).mock.calls))}`);
    },
    present: vi.fn(),
    confirm: async () => true, confirmActivation: vi.fn(async () => false), confirmReviewedDisabled: vi.fn(async () => true),
  };
  session.chooseOption = vi.fn(session.chooseOption!);
  const writeResume = async (completedOutcomes: string[], intents: string[]) => {
    await writeBoundaryAuthoringResumeState(root, buildBoundaryAuthoringResumeState({
      binding: { boundary_name: context.candidate.pack.name,
        generation_lock_fingerprint: context.bundle.authority.generation_lock_fingerprint,
        schema_fingerprint: `sha256:${"0".repeat(64)}`, role_posture_fingerprint: context.bundle.authority.role_posture_fingerprint },
      stage: "authority_review", jobIntent: "Keep the reviewed visit completion rules.", provider: "openai", model: "gpt-test",
      action: { intent: "Keep the reviewed visit completion rules.", strategy: "rule_derived", intents,
        completed_outcomes: completedOutcomes },
    }));
  };
  const chats: BoundaryAuthoringChat[] = [];
  const run = (modelActionRuleGenerator: (input: Parameters<typeof generateModelActionRuleDraft>[0]) => Promise<ModelActionRuleDraftResult>,
    actionProjectInspector: () => Promise<SchemaInspection> = async () => inspection,
    overrides: NonNullable<Parameters<typeof boundaryReviewCommandInternal>[4]> = {}) =>
    boundaryReviewCommandInternal(["--project-root", root, "--access", "--job-first"], async () => inspection,
      session, undefined, { startWithAgentJob: true, modelAuthoringSession: { provider: "openai", model: "gpt-test", apiKey: "session-secret" },
        modelBoundaryJobPlanner: planner, modelActionRuleGenerator,
        modelReadWorkloadGenerator: async () => { throw new Error("Saved dependency recovery must not remap Read or request a provider."); },
        modelAuthoringNarrator: async () => "Review the reconciled Read revision; nothing is active.",
        actionProjectInspector, boundaryAuthoringChatFactory: () => {
          const chat = testBoundaryAuthoringChat(session); chats.push(chat); return chat;
        },
        ...overrides,
      });
  const expectRetained = async (outcomes: string[]) => {
    const current = await readActionRuleAuthorityDraft(root, stored.authority.name);
    const normalized = (value: NonNullable<typeof current>) => ({
      rules: value.authority.rules.filter((rule) => outcomes.includes(rule.rule.outcome)).map(({ activated_at: _activatedAt, ...rule }) => rule),
      approval_classes: value.authority.approval_classes.filter((approval) => outcomes.includes(
        value.authority.rules.find((rule) => rule.rule.approval_class === approval.name)?.rule.outcome ?? "")),
      reviews: value.reviews.filter((review) => outcomes.includes(review.outcome)),
    });
    expect(normalized(current!)).toEqual(normalized(stored));
    await expect(readActionRuleAuthorityActivation(root)).resolves.toBeUndefined();
    await expect(loadActivatedExplorationBoundaries(root)).rejects.toMatchObject({ code: "ENOENT" });
  };
  return { root, build, written, inspection, compile, planner, session, chats, writeResume, run, expectRetained,
    dispose: () => fs.rm(root, { recursive: true, force: true }) };
}

function principalScopeInspection(options: { ambiguous?: boolean } = {}): SchemaInspection {
  const inspection = actionTargetInspection();
  for (const table of inspection.tables) {
    const nextOrdinal = Math.max(0, ...table.columns.map((column) => column.ordinal_position)) + 1;
    table.columns.push({
      name: "principal_id",
      data_type: "uuid",
      nullable: false,
      generated: false,
      ordinal_position: nextOrdinal,
      suggestions: {
        tenant: false,
        conflict: false,
        sensitive: false,
        immutable: true,
        large_or_binary: false,
      },
    });
    table.suggestions.default_visible_columns.push("principal_id");
    if (options.ambiguous) {
      table.columns.push({
        name: "owner_id",
        data_type: "uuid",
        nullable: false,
        generated: false,
        ordinal_position: nextOrdinal + 1,
        suggestions: {
          tenant: false,
          conflict: false,
          sensitive: false,
          immutable: true,
          large_or_binary: false,
        },
      });
      table.suggestions.default_visible_columns.push("owner_id");
    }
  }
  return inspection;
}

function testBoundaryAuthoringChat(
  session: BoundaryReviewInteractiveSession,
  intendedClient: "claude-code" | "later" = "later",
): BoundaryAuthoringChat {
  return {
    session: { ...session, presentationMode: "conversation",
      chooseOption: async (title, options, config) => title === "CLIENT FOR THIS JOB" ? intendedClient
        : session.chooseOption?.(title, options, config),
    },
    actionPrompter: {
      choose: async () => undefined,
      text: async () => undefined,
      confirm: async () => undefined,
      message: async () => undefined,
    },
    setModel: vi.fn(),
    setPermissionGuide: vi.fn(),
    runner: vi.fn(),
    model: vi.fn(),
    checkpoint: vi.fn(),
    streamRunner: async () => undefined,
    streamCheckpoint: async () => undefined,
    streamModel: async () => undefined,
    rememberDetails: vi.fn(),
    showDetails: vi.fn(),
    providerStream: vi.fn(),
    progress: async (_message, operation) => operation(),
    close: vi.fn(),
  };
}

function derivedFirstTableInspection(): SchemaInspection {
  const inspection = boundaryInspection();
  const orders = structuredClone(inspection.tables[0]!);
  orders.name = "orders";
  orders.unique_constraints = [{ name: "orders_pkey", columns: ["id"] }];
  orders.indexes = [{ name: "orders_pkey", columns: ["id"], unique: true }];
  const orderItems = structuredClone(orders);
  orderItems.name = "order_items";
  orderItems.columns = orderItems.columns.filter((field) =>
    field.name !== "tenant_id" && field.name !== "status" && field.name !== "scheduled_at");
  orderItems.columns.push({
    name: "order_id",
    data_type: "uuid",
    nullable: false,
    generated: false,
    ordinal_position: orderItems.columns.length + 1,
    suggestions: {
      tenant: false,
      conflict: false,
      sensitive: false,
      immutable: true,
      large_or_binary: false,
    },
  });
  orderItems.suggestions.tenant_columns = [];
  orderItems.suggestions.default_visible_columns = ["id", "order_id"];
  orderItems.row_level_security = false;
  orderItems.row_level_security_policies = [];
  orderItems.role_posture!.row_security_effective_for_current_role = false;
  orderItems.unique_constraints = [{ name: "order_items_pkey", columns: ["id"] }];
  orderItems.indexes = [{ name: "order_items_pkey", columns: ["id"], unique: true }];
  orderItems.foreign_keys = [{
    name: "order_items_order_id_fkey",
    columns: ["order_id"],
    referenced_schema: "public",
    referenced_table: "orders",
    referenced_columns: ["id"],
    delete_rule: "RESTRICT",
  }];
  inspection.tables = [orderItems, orders];
  return inspection;
}

function depthThreeDerivedCliInspection(): SchemaInspection {
  const inspection = derivedFirstTableInspection();
  const orderItems = inspection.tables.find((table) => table.name === "order_items")!;
  const orders = inspection.tables.find((table) => table.name === "orders")!;
  const derivedChild = (
    source: typeof orderItems,
    name: string,
    foreignKeyField: string,
    target: string,
    constraint: string,
  ) => {
    const table = structuredClone(source);
    table.name = name;
    table.columns = table.columns.filter((field) => field.name === "id");
    const foreignKey = structuredClone(source.columns.find((field) => field.name !== "id")!);
    foreignKey.name = foreignKeyField;
    foreignKey.ordinal_position = 2;
    table.columns.push(foreignKey);
    table.primary_key = ["id"];
    table.unique_constraints = [{ name: `${name}_pkey`, columns: ["id"] }];
    table.indexes = [{ name: `${name}_pkey`, columns: ["id"], unique: true }];
    table.foreign_keys = [{
      name: constraint,
      columns: [foreignKeyField],
      referenced_schema: "public",
      referenced_table: target,
      referenced_columns: ["id"],
      delete_rule: "RESTRICT",
    }];
    table.suggestions.default_visible_columns = ["id", foreignKeyField];
    return table;
  };
  const orderEvents = derivedChild(
    orderItems,
    "order_events",
    "order_item_id",
    "order_items",
    "order_events_order_item_id_fkey",
  );
  const eventNotes = derivedChild(
    orderEvents,
    "event_notes",
    "order_event_id",
    "order_events",
    "event_notes_order_event_id_fkey",
  );
  inspection.tables = [eventNotes, orderEvents, orderItems, orders];
  return inspection;
}

function derivedPrincipalFirstTableInspection(singleOrganization: boolean): SchemaInspection {
  const inspection = boundaryInspection();
  const orders = structuredClone(inspection.tables[0]!);
  orders.name = "orders";
  orders.columns.push({
    name: "owner_id",
    data_type: "uuid",
    nullable: false,
    generated: false,
    ordinal_position: orders.columns.length + 1,
    suggestions: {
      tenant: false,
      conflict: false,
      sensitive: false,
      immutable: true,
      large_or_binary: false,
    },
  });
  orders.suggestions.default_visible_columns.push("owner_id");
  orders.unique_constraints = [{ name: "orders_pkey", columns: ["id"] }];
  orders.indexes = [{ name: "orders_pkey", columns: ["id"], unique: true }];

  const orderItems = structuredClone(orders);
  orderItems.name = "order_items";
  orderItems.columns = orderItems.columns.filter((field) =>
    field.name !== "owner_id" && field.name !== "status" && field.name !== "scheduled_at");
  orderItems.columns.push({
    name: "order_id",
    data_type: "uuid",
    nullable: false,
    generated: false,
    ordinal_position: orderItems.columns.length + 1,
    suggestions: {
      tenant: false,
      conflict: false,
      sensitive: false,
      immutable: true,
      large_or_binary: false,
    },
  });
  orderItems.suggestions.default_visible_columns = orderItems.columns.map((field) => field.name);
  orderItems.unique_constraints = [{ name: "order_items_pkey", columns: ["id"] }];
  orderItems.indexes = [{ name: "order_items_pkey", columns: ["id"], unique: true }];
  orderItems.foreign_keys = [{
    name: "order_items_order_id_fkey",
    columns: ["order_id"],
    referenced_schema: "public",
    referenced_table: "orders",
    referenced_columns: ["id"],
    delete_rule: "RESTRICT",
  }];
  if (singleOrganization) {
    for (const table of [orders, orderItems]) {
      table.columns = table.columns.filter((field) => field.name !== "tenant_id");
      table.suggestions.tenant_columns = [];
      table.suggestions.default_visible_columns =
        table.suggestions.default_visible_columns.filter((field) => field !== "tenant_id");
      table.row_level_security = false;
      table.row_level_security_policies = [];
      if (table.role_posture) {
        table.role_posture.row_security_effective_for_current_role = false;
      }
    }
  }
  inspection.tables = [orderItems, orders];
  return inspection;
}

